const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let pdf = null;

  // Cas 3 : c'est déjà un PDF
  if (buf.subarray(0, 4).toString('latin1') === '%PDF') {
    pdf = buf;
  } else {
    const txt = buf.toString('latin1');

    // Cas 1 : e-mail MIME, on cherche la partie PDF en base64
    const parts = txt.split(/\r?\n--[^\r\n]+/);
    for (const part of parts) {
      const idx = part.search(/\r?\n\r?\n/);
      if (idx === -1) continue;
      const header = part.slice(0, idx);
      const body = part.slice(idx).replace(/\s+/g, '');
      if (/application\/pdf|\.pdf/i.test(header) && /base64/i.test(header)) {
        pdf = Buffer.from(body, 'base64');
        break;
      }
    }

    // Cas 2 : tout le fichier est du base64
    if (!pdf) {
      const compact = txt.replace(/\s+/g, '');
      if (compact.startsWith('JVBER')) pdf = Buffer.from(compact, 'base64');
    }
  }

  if (!pdf) throw new Error('Aucun PDF trouvé dans ce fichier');

  const binary = await this.helpers.prepareBinaryData(pdf, 'devis.pdf', 'application/pdf');
  out.push({ json: items[i].json, binary: { data: binary } });
}

return out;

const { PDFDocument } = require('pdf-lib');

const merged = await PDFDocument.create();
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const doc = await PDFDocument.load(buf, { ignoreEncryption: true });
  const pages = await merged.copyPages(doc, doc.getPageIndices());
  pages.forEach(p => merged.addPage(p));
}

const bytes = await merged.save();
const binary = await this.helpers.prepareBinaryData(
  Buffer.from(bytes), 'devis.pdf', 'application/pdf'
);

return [{ json: { nb_pdf: items.length }, binary: { data: binary } }];
